import base64
from pathlib import Path
p = Path("webcms/admin/admin_api.py")
lines = p.read_text().splitlines(keepends=True)

# Find start of KosDB block (line with "if self._is_kosdb():" inside update_settings)
method_start = None
for i, line in enumerate(lines):
    if "def update_settings(self, request: Request) -> Response:" in line:
        method_start = i
        break
else: raise SystemExit("no update_settings")

start = None
for i in range(method_start, len(lines)):
    if "if self._is_kosdb():" in lines[i]:
        start = i
        break
else: raise SystemExit("no kosdb block")

end = None
for i in range(start+1, len(lines)):
    if lines[i].strip() == "else:":
        end = i
        break
else: raise SystemExit("no else block")

new_block = base64.b64decode("").decode()

lines = lines[:start] + [new_block] + lines[end:]
with open(str(p), "w") as f: f.writelines(lines)
print("fixed update_settings block")